function summary=validate_hcp_stage3_generalization(workspace)
%VALIDATE_HCP_STAGE3_GENERALIZATION 旧beta的跨人/跨run冻结应用与行为摘要ICC。
if nargin<1,workspace=fileparts(fileparts(fileparts(mfilename('fullpath'))));end
addpath(fullfile(workspace,'function_toolkit'));setup_function('D:/matlab/atoolbox/spm12');out=fullfile(workspace,'derivatives','function_stage3_generalization_20261017');if isfolder(out),error('cog:Exists','Preserve results');end;mkdir(out);
catalog=fullfile(workspace,'derivatives','function_stage1_real_20261016','patterns_results','selected_catalog.tsv');[x,meta,space]=cog.load_betas(catalog,1);ids=string(space.indices);subjects=unique(meta.subject,'stable');c=transfer_config;c.execute=true;c.options.dependencyNote='Engineering shared-grid sparse mask. Existing TYPEB betas share within-subject HRF estimation across runs; no fully independent upstream CV or family evidence.';
for k=1:numel(subjects)
    use=meta.subject==subjects(k);train=domain(x(use,:),meta(use,:),ids,"subject_"+subjects(k));test=domain(x(~use,:),meta(~use,:),ids,"other_subjects");c.dataFile=fullfile(out,"cross_subject_"+subjects(k)+".mat");save(c.dataFile,'train','test');c.outputRoot=fullfile(out,"cross_subject_"+subjects(k));r=run_transfer(c);summary.crossSubject(k)=struct('source',subjects(k),'accuracy',r.accuracy,'nTarget',size(test.X,1));
end
use=meta.subject==subjects(1);sub=meta(use,:);a=x(use,:);runs=unique(sub.run,'stable');left=sub.run==runs(1);train=domain(a(left,:),sub(left,:),ids,"run_"+runs(1));test=domain(a(~left,:),sub(~left,:),ids,"run_other");c.options.unitPolicy='matched_units_distinct_domains';c.dataFile=fullfile(out,'cross_run.mat');save(c.dataFile,'train','test');c.outputRoot=fullfile(out,'cross_run');r=run_transfer(c);summary.crossRunAccuracy=r.accuracy;
subjects=["100206";"100307";"100408"];y=zeros(3,2,2);for s=1:3,for run=1:2,direction=["LR" "RL"];tr=cog.read_tsv(fullfile(workspace,'derivatives','function_stage3_behavior_20261017',subjects(s)+"_"+direction(run)+"_trials.tsv"));y(s,run,1)=mean(str2double(tr.rt_seconds));y(s,run,2)=mean(str2double(tr.reward));end,end
data=struct('y',y,'unitIds',subjects,'occasionIds',["LANGUAGE_LR";"LANGUAGE_RL"],'featureIds',["mean_first_option_rt_seconds";"accuracy_proxy"]);file=fullfile(out,'icc_input.mat');save(file,'data');c=reliability_config;c.dataFile=file;c.outputRoot=fullfile(out,'icc');c.execute=true;c.options.designNote='Three engineering subjects, LR/RL task runs with different trial mixtures; RT starts first audio option, accuracy is proxy. Same visit, not longitudinal test-retest; point ICC only.';r=run_reliability(c);summary.icc=r.values;
summary.scope='50 existing TYPEB units in shared cross-subject mask, two source-to-other-subject transfers and one known-subject LR-to-RL frozen diagLDA. Source scales/model fixed. ICC six definitions on 3x2 RT/accuracy aggregates, no CI.';summary.skipped={'Real cross-task/longitudinal cross-session transfer: prepared TYPEB estimates cover LANGUAGE same visit only; generic distinct-domain interface tested synthetically.','Real item split-half: aligned common-item behavioral measurement matrix not prepared; generic matched-item and random balanced functions tested synthetically. Different trials were not silently treated as matched items.'};cog.write_json(fullfile(out,'VALIDATION.json'),summary);
end
function a=domain(x,t,ids,name)
a=struct('X',x,'Y',t.condition,'featureIds',ids,'sampleIds',t.estimate_id,'independentUnitIds',t.subject,'domainId',name);
end
